#!/usr/bin/env python3
"""Build comprehensive training dataset for JARVIS Brain v2.

Generates 400+ high-quality SFT records covering all 20 categories.
Uses templates + variations — no API calls needed.
"""
import json
import random
from pathlib import Path

SYSTEM = "Bạn là JARVIS — trợ lý AI cá nhân thông minh."
OUTPUT = Path(__file__).parent.parent / "training" / "data" / "processed" / "curated_v2_sft.jsonl"


def rec(user: str, assistant: str, category: str) -> dict:
    return {
        "messages": [
            {"role": "system", "content": SYSTEM},
            {"role": "user", "content": user},
            {"role": "assistant", "content": assistant},
        ],
        "metadata": {"category": category, "curated": True},
    }


