def build_all() -> list[dict]:
    """Combine all categories."""
    all_data = []
    generators = [
        greeting_vn, jarvis_identity, factual_vn, vietnamese_culture,
        python_coding, algorithms, web_development, devops, networking,
        data_analysis, math_logic, planning, writing_assist, daily_tasks,
        conversation, english_general, english_coding, error_handling,
        security, finance,
    ]
    for gen in generators:
        records = gen()
        all_data.extend(records)
        print(f"  {gen.__name__}: {len(records)} records")
    return all_data


def main():
    print("Building comprehensive training dataset...")
    records = build_all()

    # Stats
    from collections import Counter
    cats = Counter(r["metadata"]["category"] for r in records)
    print(f"\nTotal: {len(records)} records across {len(cats)} categories")
    for cat, count in sorted(cats.items()):
        print(f"  {cat}: {count}")

    # Save
    OUTPUT.parent.mkdir(parents=True, exist_ok=True)
    with open(OUTPUT, "w", encoding="utf-8") as f:
        for r in records:
            f.write(json.dumps(r, ensure_ascii=False) + "\n")
    print(f"\nSaved to {OUTPUT}")


if __name__ == "__main__":
    main()
